29	/// Load the preferred requirements from an existing `requirements.txt`, applying the upgrade strategy.
30	pub async fn read_requirements_txt(
31	    output_file: &Path,
32	    upgrade: &Upgrade,
33	) -> Result<Vec<Preference>> {
34	    // As an optimization, skip reading the lockfile is we're upgrading all packages anyway.
35	    if upgrade.is_all() {
36	        return Ok(Vec::new());
37	    }
38	
39	    // Parse the requirements from the lockfile.
40	    let requirements_txt = RequirementsTxt::parse(output_file, &*CWD).await?;
41	
42	    // Map each entry in the lockfile to a preference.
43	    let preferences = requirements_txt
44	        .requirements
45	        .into_iter()
46	        .map(Preference::from_entry)
47	        .filter_map(Result::transpose)
48	        .collect::<Result<Vec<_>, PreferenceError>>()?;
49	
50	    // Apply the upgrade strategy to the requirements.
51	    Ok(match upgrade {
52	        // Respect all pinned versions from the existing lockfile.
53	        Upgrade::None => preferences,
54	        // Ignore all pinned versions from the existing lockfile.
55	        Upgrade::All => vec![],
56	        // Ignore pinned versions for the specified packages.
57	        Upgrade::Packages(packages) => preferences
58	            .into_iter()
59	            .filter(|preference| !packages.contains_key(preference.name()))
60	            .collect(),
61	    })
62	}
