64	/// Load the preferred requirements from an existing lockfile, applying the upgrade strategy.
65	pub fn read_lock_requirements(
66	    lock: &Lock,
67	    install_path: &Path,
68	    upgrade: &Upgrade,
69	) -> Result<LockedRequirements, LockError> {
70	    // As an optimization, skip iterating over the lockfile is we're upgrading all packages anyway.
71	    if upgrade.is_all() {
72	        return Ok(LockedRequirements::default());
73	    }
74	
75	    let mut preferences = Vec::new();
76	    let mut git = Vec::new();
77	
78	    for package in lock.packages() {
79	        // Skip the distribution if it's not included in the upgrade strategy.
80	        if upgrade.contains(package.name()) {
81	            continue;
82	        }
83	
84	        // Map each entry in the lockfile to a preference.
85	        if let Some(preference) = Preference::from_lock(package, install_path)? {
86	            preferences.push(preference);
87	        }
88	
89	        // Map each entry in the lockfile to a Git SHA.
90	        if let Some(git_ref) = package.as_git_ref()? {
91	            git.push(git_ref);
92	        }
93	    }
94	
95	    Ok(LockedRequirements { preferences, git })
96	}
