    /// The strategy for determining which packages to consider for upgrade.
    pub strategy: UpgradeStrategy,

    /// Per-package version constraints on the upgrade (e.g., `--upgrade-package flask<3`).
    pub constraints: FxHashMap<PackageName, Vec<Requirement>>,
}

