134	/// Strategy for determining which packages to consider for upgrade.
135	#[derive(Debug, Default, Clone)]
136	pub enum UpgradeStrategy {
137	    /// Prefer pinned versions from the existing lockfile, if possible.
138	    #[default]
139	    None,
140	
141	    /// Allow package upgrades for all packages, ignoring the existing lockfile.
142	    All,
143	
144	    /// Allow package upgrades, but only for the specified packages.
145	    Packages(FxHashSet<PackageName>),
146	}
147	
148	/// Whether to allow package upgrades.
149	///
150	/// Combines an [`UpgradeStrategy`], determining which packages to consider for upgrade, with
151	/// per-package version constraints on those upgrades (e.g., `--upgrade-package flask<3`).
152	#[derive(Debug, Default, Clone)]
153	pub struct Upgrade {
154	    /// The strategy for determining which packages to consider for upgrade.
155	    pub strategy: UpgradeStrategy,
156	
157	    /// Per-package version constraints on the upgrade (e.g., `--upgrade-package flask<3`).
158	    pub constraints: FxHashMap<PackageName, Vec<Requirement>>,
159	}
160	
161	impl Upgrade {
162	    /// Determine the upgrade selection strategy from the command-line arguments.
163	    pub fn from_args(upgrade: Option<bool>, upgrade_package: Vec<Requirement>) -> Option<Self> {
164	        // Collect the version constraints for the specified packages, skipping any without a
165	        // version specifier (e.g., a bare `--upgrade-package flask`).
166	        let constraints = upgrade_package.iter().cloned().fold(
167	            FxHashMap::<PackageName, Vec<Requirement>>::default(),
168	            |mut map, requirement| {
169	                if let RequirementSource::Registry { specifier, .. } = &requirement.source {
170	                    if specifier.is_empty() {
171	                        return map;
172	                    }
173	                }
174	                map.entry(requirement.name.clone())
175	                    .or_default()
176	                    .push(requirement);
177	                map
178	            },
179	        );
180	
181	        match upgrade {
182	            Some(true) => Some(Self {
183	                strategy: UpgradeStrategy::All,
184	                constraints,
185	            }),
186	            Some(false) if upgrade_package.is_empty() => Some(Self {
187	                strategy: UpgradeStrategy::None,
188	                constraints,
