194	                strategy: UpgradeStrategy::Packages(
195	                    upgrade_package
196	                        .into_iter()
197	                        .map(|requirement| requirement.name)
198	                        .collect(),
199	                ),
200	                constraints,
201	            }),
202	        }
203	    }
